            shape: 'a subject + a past simple trend verb + an adverb', expect: 'Sales then rose slowly (also accepted: Sales then increased gradually / Sales grew slowly / Sales then rose modestly)',
            accept: [['sales|they|the (number|figure|total)'], ['\\brose\\b|increased|grew|climbed|went up'], ['slowly|gradually|slightly|modestly|a little']],
